@page "/board"
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h1 class="mb-3">Kanban Board</h1>

@if (isLoading)
{
    <div class="d-flex justify-content-center my-5">
        <div class="spinner-border" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
    </div>
}
else if (errorMessage is not null)
{
    <div class="alert alert-danger" role="alert">
        <strong>Error:</strong> @errorMessage
    </div>
}
else
{
    <!-- Stats Bar -->
    <div class="row g-2 mb-3">
        <div class="col">
            <div class="card text-center stats-card">
                <div class="card-body py-2">
                    <div class="fw-bold">Total</div>
                    <div class="fs-4">@allTasks.Count</div>
                </div>
            </div>
        </div>
        @foreach (var col in columns)
        {
            <div class="col">
                <div class="card text-center stats-card">
                    <div class="card-body py-2">
                        <div class="fw-bold">@col</div>
                        <div class="fs-4">@CountByStatus(col)</div>
                    </div>
                </div>
            </div>
        }
        <div class="col">
            <div class="card text-center stats-card overdue">
                <div class="card-body py-2">
                    <div class="fw-bold">Overdue</div>
                    <div class="fs-4">@allTasks.Count(t => t.DueDate.Date < DateTime.Today)</div>
                </div>
            </div>
        </div>
    </div>

    <!-- Search Bar -->
    <div class="mb-3">
        <input type="text" class="form-control" placeholder="Search tasks by title..."
               @bind="searchText" @bind:event="oninput" />
    </div>

    <!-- Kanban Columns -->
    <div class="row g-3">
        @for (int i = 0; i < columns.Length; i++)
        {
            var colIndex = i;
            var colName = columns[colIndex];
            var tasks = GetFilteredTasks(colName);

            <div class="col-md-4">
                <div class="card kanban-column">
                    <div class="card-header d-flex justify-content-between align-items-center">
                        <span class="fw-bold">@colName</span>
                        <span class="badge bg-secondary rounded-pill">@tasks.Count</span>
                    </div>
                    <div class="card-body kanban-body">
                        @foreach (var task in tasks)
                        {
                            <div class="card task-card mb-2">
                                <div class="card-body p-2">
                                    <div class="fw-semibold mb-1">@task.Title</div>
                                    <div class="d-flex justify-content-between align-items-center mb-1">
                                        <small class="text-muted">@task.Assignee</small>
                                        <span class="badge priority-badge @GetPriorityClass(task.Priority)">
                                            @task.Priority
                                        </span>
                                    </div>
                                    <div class="d-flex justify-content-between align-items-center">
                                        <small class="text-muted">@task.DueDate.ToString("MMM dd")</small>
                                        <div>
                                            @if (colIndex > 0)
                                            {
                                                <button class="btn btn-sm btn-outline-secondary me-1"
                                                        @onclick="() => MoveTask(task.Id, columns[colIndex - 1])"
                                                        disabled="@isBusy">
                                                    &larr;
                                                </button>
                                            }
                                            @if (colIndex < columns.Length - 1)
                                            {
                                                <button class="btn btn-sm btn-outline-secondary"
                                                        @onclick="() => MoveTask(task.Id, columns[colIndex + 1])"
                                                        disabled="@isBusy">
                                                    &rarr;
                                                </button>
                                            }
                                        </div>
                                    </div>
                                </div>
                            </div>
                        }

                        @if (addingToColumn == colName)
                        {
                            <div class="card mb-2 border-primary">
                                <div class="card-body p-2">
                                    <input type="text" class="form-control form-control-sm mb-1"
                                           placeholder="Title" @bind="newTitle" />
                                    <input type="text" class="form-control form-control-sm mb-1"
                                           placeholder="Assignee" @bind="newAssignee" />
                                    <select class="form-select form-select-sm mb-1" @bind="newPriority">
                                        <option value="High">High</option>
                                        <option value="Medium">Medium</option>
                                        <option value="Low">Low</option>
                                    </select>
                                    <input type="date" class="form-control form-control-sm mb-2"
                                           @bind="newDueDate" />
                                    <div class="d-flex gap-1">
                                        <button class="btn btn-sm btn-primary flex-fill"
                                                @onclick="() => SaveNewTask(colName)"
                                                disabled="@isBusy">
                                            Save
                                        </button>
                                        <button class="btn btn-sm btn-outline-secondary flex-fill"
                                                @onclick="CancelAdd"
                                                disabled="@isBusy">
                                            Cancel
                                        </button>
                                    </div>
                                </div>
                            </div>
                        }
                    </div>
                    <div class="card-footer text-center">
                        <button class="btn btn-sm btn-outline-primary w-100"
                                @onclick="() => ShowAddForm(colName)"
                                disabled="@(addingToColumn is not null)">
                            + Add Task
                        </button>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    private readonly string[] columns = ["To Do", "In Progress", "Done"];

    private List<TaskItem> allTasks = new();
    private bool isLoading = true;
    private bool isBusy;
    private string? errorMessage;
    private string searchText = string.Empty;

    // Add-task form state
    private string? addingToColumn;
    private string newTitle = string.Empty;
    private string newAssignee = string.Empty;
    private string newPriority = "Medium";
    private DateTime newDueDate = DateTime.Today.AddDays(7);

    protected override async Task OnInitializedAsync()
    {
        try
        {
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
        finally
        {
            isLoading = false;
        }
    }

    private int CountByStatus(string status) =>
        allTasks.Count(t => t.Status == status);

    private List<TaskItem> GetFilteredTasks(string status) =>
        allTasks
            .Where(t => t.Status == status &&
                        t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase))
            .ToList();

    private static string GetPriorityClass(string priority) => priority switch
    {
        "High" => "priority-high",
        "Medium" => "priority-medium",
        "Low" => "priority-low",
        _ => ""
    };

    private async Task MoveTask(int taskId, string newStatus)
    {
        isBusy = true;
        try
        {
            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
            var idx = allTasks.FindIndex(t => t.Id == taskId);
            if (idx >= 0)
            {
                allTasks[idx] = allTasks[idx] with { Status = newStatus };
            }
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
        finally
        {
            isBusy = false;
        }
    }

    private void ShowAddForm(string column)
    {
        addingToColumn = column;
        newTitle = string.Empty;
        newAssignee = string.Empty;
        newPriority = "Medium";
        newDueDate = DateTime.Today.AddDays(7);
    }

    private void CancelAdd() => addingToColumn = null;

    private async Task SaveNewTask(string column)
    {
        if (string.IsNullOrWhiteSpace(newTitle))
            return;

        isBusy = true;
        try
        {
            var created = await TaskService.CreateTaskAsync(newTitle.Trim(), newAssignee.Trim(), newPriority, newDueDate);
            // The service creates tasks; if it doesn't set the status to the target column, patch locally.
            if (created.Status != column)
            {
                await TaskService.UpdateTaskStatusAsync(created.Id, column);
                created = created with { Status = column };
            }
            allTasks.Add(created);
            addingToColumn = null;
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
        finally
        {
            isBusy = false;
        }
    }
}

.kanban-column {
    min-height: 400px;
    display: flex;
    flex-direction: column;
}

.kanban-body {
    flex: 1;
    overflow-y: auto;
    max-height: 60vh;
}

.task-card {
    transition: box-shadow 0.15s;
}

.task-card:hover {
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.12);
}

.stats-card.overdue {
    border-color: #dc3545;
    color: #dc3545;
}

.priority-badge.priority-high {
    background-color: #dc3545;
    color: #fff;
}

.priority-badge.priority-medium {
    background-color: #ffc107;
    color: #212529;
}

.priority-badge.priority-low {
    background-color: #198754;
    color: #fff;
}

